            self.GiftPackApplyUI:SetVisibility(ESlateVisibility.Collapsed);
        end
    end)
    Common.LoadObjectWithSoftPathAsync(self.GiftPackComplexUIPath, function(Object)
        if self ~= nil and Object ~= nil then
